from typing import List

class Solution:
    def totalFruit(self, fruits: List[int]) -> int:
        best = 0
        for left in range(len(fruits)):
            types = set()
            for right in range(left, len(fruits)):
                types.add(fruits[right])
                if len(types) > 2:
                    break
                best = max(best, right - left + 1)
        return best

